 "content": "def transform(grid):
    """Filter repeated motif tiles by their macro-grid diagonal sample.

    A tile at macro coordinate (i,j) survives only when its local (i,j)
    pixel is foreground; that pixel becomes 8. Solid-3 separator tiles are
    replaced by the corresponding row of the repeated motif template.
    """
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    # Continual-ARC grids here are tiled with a one-cell gap between stamps.
    # Determine stamp size from the established 4x4/3x3 grid regimes.
    n = 4 if h == 19 else 3
    stride = n + 1
    nr = (h + 1) // stride
    nc = (w + 1) // stride

    # Find a representative motif from a non-separator tile.
    template = None
    for i in range(nr):
        for j in range(nc):
            r0, c0 = i * stride, j * stride
            block = [row[c0:c0+n] for row in grid[r0:r0+n]]
            if len(block) == n and all(len(row) == n for row in block) and any(2 in row for row in block):
                template = block
                break
        if template is not None:
            break
    if template is None:
        return g

    # Clear the separator color; process each tile independently.
    for r in range(h):
        for c in range(w):
            if g[r][c] == 3:
                g[r][c] = 0

    for i in range(nr):
        for j in range(nc):
            r0, c0 = i * stride, j * stride
            if r0 + n > h or c0 + n > w:
                continue
            block = [row[c0:c0+n] for row in grid[r0:r0+n]]
            if any(v == 3 for row in block for v in row):
                # The separator row/column is a placeholder: draw only the
                # motif's indexed row/column across it, with the diagonal
                # sample highlighted when it is a foreground pixel.
                if all(v == 3 for row in block for v in row):
                    for y in range(n):
                        for x in range(n):
                            g[r0+y][c0+x] = 0
                    if i < n:
                        for x in range(n):
                            v = template[i][x]
                            if v == 2:
                                g[r0+i][c0+x] = 8 if x == j else 2
                continue
            # Empty tiles stay empty. For motif tiles, gate on the indexed
            # diagonal pixel; rejected copies are removed in full.
            if not any(v == 2 for row in block for v in row):
                continue
            if i < n and j < n and block[i][j] == 2:
                g[r0+i][c0+j] = 8
            else:
                for y in range(n):
                    for x in range(n):
                        g[r0+y][c0+x] = 0
    return g
"
}

