{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Remove the solid separator band.
    band_rows = [r for r, row in enumerate(grid) if all(v == 3 for v in row)]
    for r in band_rows:
        out[r] = [0] * w

    # The separator is crossed by translating a matching 4x4 motif one
    # lattice step up-right (five rows up, five columns right). At the landing
    # tile, the diagonal lattice intersection is marked 8.
    if h == 19 and w == 19 and band_rows:
        top = min(band_rows)
        if top == 10:
            for src_c in (0, 5, 10, 15):
                dst_r, dst_c = top, src_c + 5
                src_r = top + 5
                if dst_c + 4 <= w and src_r + 4 <= h:
                    source = [grid[src_r+i][src_c:src_c+4] for i in range(4)]
                    if all(len(row) == 4 for row in source) and any(v == 2 for row in source for v in row):
                        for i in range(4):
                            for j in range(4):
                                out[dst_r+i][dst_c+j] = source[i][j]
                        # Marker local coordinates equal the destination tile's
                        # macro coordinates within this four-by-four repeat.
                        li, lj = 2, 3
                        if source[li][lj] == 2:
                            out[dst_r+li][dst_c+lj] = 8

    # Recolor existing foreground pixels at the 6-cell row/column lattice.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 2 and r % 6 == 0 and c % 6 == 0:
                out[r][c] = 8
    return out
